/**
 * The content overlay: the DIFFERENCES between what the database says learners should see (published
 * questions) and what the code registries contain. An empty overlay means "serve the code as-is", which
 * is exactly how the learner app behaved before the database existed. It is tiny by design, so it adds
 * almost nothing to the learner bundle (a full second copy of 5,000 questions would).
 *
 * It is generated by `npm run content:publish` and committed, so a publish is reviewable in git and
 * applied by a normal deploy. Learners never query the database.
 */
import type { QuizQuestion } from "@/features/quiz-engine/types";
import type { MptQuestion } from "@/features/mpt-mock/data/mpt-mock-data";
import type { ExamType, TeacherQuestion } from "@/features/teacher-tests/types";

export interface ListOverlay<T> {
  /** id → the question as learners should now see it. */
  replace?: Record<string, T>;
  /** ids taken out of use (archived / unpublished / removed from the bank). */
  remove?: string[];
  /** questions that exist only in the database, appended in order. */
  add?: T[];
}

export interface QuizBankOverlay extends ListOverlay<QuizQuestion> {
  /** Full id order, only present when it differs from (code order minus removals, plus additions). */
  order?: string[];
}

export interface ContentOverlay {
  version: 1;
  generatedAt: string | null;
  /** keyed by quiz bank id (slug) */
  quiz: Record<string, QuizBankOverlay>;
  /** CSS MPT: only edits to existing questions can reach learners (mocks are fixed lists). */
  mpt: { replace?: Record<string, MptQuestion> };
  teacher: Partial<Record<ExamType, ListOverlay<TeacherQuestion>>>;
}

export interface Manifest {
  version: 1;
  generatedAt: string | null;
  /** "system:legacy_id" → "<status>|<content_hash>" for every question at publish time. */
  questions: Record<string, string>;
  /** What the last publish contained (counts), written by the publish script. */
  report?: unknown;
}

export const EMPTY_OVERLAY: ContentOverlay = { version: 1, generatedAt: null, quiz: {}, mpt: {}, teacher: {} };

export interface SkippedItem { scope: string; id: string; why: string }
